async def act(page):
    # Prefer the readable site-title link inside the heading, fall back to the home icon link.
    heading = page.get_by_role("heading", name="Epoch & Drift Benchmark")
    home_link = None

    if await heading.count() > 0:
        candidate = heading.get_by_role("link", name="Epoch & Drift Benchmark")
        if await candidate.count() > 0:
            home_link = candidate

    # If we didn't find the heading->link, try top-level text link, then icon fallback.
    if home_link is None:
        candidate = page.get_by_role("link", name="Epoch & Drift Benchmark")
        if await candidate.count() > 0:
            home_link = candidate

    if home_link is None:
        candidate = page.get_by_role("link", name="")
        if await candidate.count() > 0:
            home_link = candidate

    # If no home link found, nothing to do.
    if home_link is None:
        return

    # Click the link (last meaningful action) and then wait for load state to ensure navigation completes.
    await home_link.click()

    try:
        await page.wait_for_load_state("load", timeout=5000)
    except Exception:
        try:
            await page.wait_for_load_state("domcontentloaded", timeout=5000)
        except Exception:
            # Best-effort; the click was issued.
            pass

